node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

// Search order_items for PROD-FA0948
const orderItems = db.prepare(\"SELECT * FROM order_items WHERE product_id = 'PROD-FA0948'\").all();
console.log('=== ORDER ITEMS ===');
console.log(JSON.stringify(orderItems, null, 2));

// Get parent orders
if (orderItems.length > 0) {
    const orderIds = [...new Set(orderItems.map(oi => oi.order_id))];
    for (const oid of orderIds) {
        const order = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(oid);
        console.log('\n=== ORDER: ' + oid + ' ===');
        console.log(JSON.stringify(order, null, 2));
    }
}

// Search warranties
const warranties = db.prepare(\"SELECT * FROM warranties WHERE product_id = 'PROD-FA0948'\").all();
console.log('\n=== WARRANTIES ===');
console.log(JSON.stringify(warranties, null, 2));

db.close();
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Update order_items: mark item as exchanged
db.prepare(\`
  UPDATE order_items
  SET item_status = 'exchanged',
      return_reason = 'defective',
      replacement_item_id = 'PROD-FA0948',
      return_label_issued = 1
  WHERE oi_id = 'ITEM-4D9AFC' AND order_id = 'ORD-66CC25'
\`).run();

// Update orders: record exchange details
db.prepare(\`
  UPDATE orders
  SET exchange_items = 'ITEM-4D9AFC',
      exchange_new_items = 'PROD-FA0948',
      exchange_price_difference = 0.0
  WHERE order_id = 'ORD-66CC25'
\`).run();

// Verify changes
const item = db.prepare(\"SELECT * FROM order_items WHERE oi_id = 'ITEM-4D9AFC'\").get();
const order = db.prepare(\"SELECT order_id, status, exchange_items, exchange_new_items, exchange_price_difference FROM orders WHERE order_id = 'ORD-66CC25'\").get();

console.log('=== Updated Order Item ===');
console.log(JSON.stringify(item, null, 2));
console.log('\n=== Updated Order (exchange fields) ===');
console.log(JSON.stringify(order, null, 2));

db.close();
"
